function busy(form,value){form.querySelector('button[type=submit]').disabled=value}
function setMode(mode){$$('[data-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.mode===mode);b.setAttribute('aria-selected',b.dataset.mode===mode)});$$('.mode').forEach(s=>s.hidden=s.id!==`mode-${mode}`)}
