function coverageText(country){const count=records.filter(p=>p.country===country).length;return `${count} bornes intégrées pour ${config.countries[country].name}. ${country==='ES'?'Couverture officielle partielle autour de Valencia.':country==='FR'?'Couverture officielle partielle autour d’Angers. Les PR sont liés à une section et à un côté.':'Pas de référentiel officiel intégré pour ce pays. Recherche ponctuelle possible dans OpenStreetMap.'} Aucune interpolation ; une borne absente n’est pas localisable avec certitude.`}
function updateCoverage(){const country=$('#country').value;$('#pk-coverage').textContent=coverageText(country);const found=[...new Set(records.filter(p=>p.country===country).map(p=>p.road))].sort();$('#road-list').innerHTML=found.map(r=>`<option value="${esc(r)}">`).join('')}
