function showCity(c,name){selectedCity={...c,name};candidateLayer.clearLayers();map.setView([c.lat,c.lon],11);$('#map-title').textContent=`${name} · ${c.countryName||'zone de recherche'}`;$('#city-results').innerHTML=`<div class="result-card"><strong>${esc(name)}</strong><small>Carte centrée sur la localité. Grands axes en bleu. Zoomez pour afficher les bornes et les repères.</small><small>${esc(c.source||'OpenStreetMap / Nominatim')} · coordonnées du centre cartographique</small></div>`;message(inSnapshot(c)?'Secteur intégré : autoroutes visibles. Zoomez jusqu’à 14 pour explorer les bornes et les repères.':'Carte centrée. Utilisez « Rechercher les données de cette zone » pour charger les grands axes et les bornes.');$('#sidebar')?.classList.remove('collapsed');renderMap()}
async function searchCity(name){clearSelection();const token=++cityToken;busy($('#city-form'),true);$('#city-results').textContent='Recherche de la localité…';try{const key=Object.keys(snapshot.cities).find(k=>normalize(k)===normalize(name)||normalize(snapshot.cities[k].name)===normalize(name));if(key){const c=snapshot.cities[key];showCity(c,c.name);return}const rows=await nominatim('search',{q:name,countrycodes:'fr,es,pt,de,it',limit:'5',featuretype:'settlement'});if(token!==cityToken)return;if(!rows.length){$('#city-results').textContent='Aucune localité trouvée dans les cinq pays couverts.';return}$('#city-results').innerHTML='';for(const row of rows){const b=document.createElement('button');b.className='result-card';b.innerHTML=`<strong>${esc(row.name)}</strong><small>${esc(row.display_name)}</small>`;b.onclick=()=>showCity({lat:+row.lat,lon:+row.lon,countryName:row.address?.country,source:'OpenStreetMap / Nominatim'},row.name);$('#city-results').append(b)}const row=rows[0];showCity({lat:+row.lat,lon:+row.lon,countryName:row.address?.country,source:'OpenStreetMap / Nominatim'},row.name);if(rows.length>1){const choices=document.createElement('details');choices.innerHTML='<summary>Autres localités correspondantes</summary>';for(const r of rows.slice(1)){const b=document.createElement('button');b.className='result-card';b.textContent=r.display_name;b.onclick=()=>showCity({lat:+r.lat,lon:+r.lon,countryName:r.address?.country},r.name);choices.append(b)}$('#city-results').append(choices)}}catch(e){$('#city-results').textContent=errorText(e);message('La localité n’a pas pu être recherchée. La carte reste disponible.',true)}finally{if(token===cityToken)busy($('#city-form'),false)}}
$('#city-form').onsubmit=e=>{e.preventDefault();searchCity($('#city').value.trim())};$$('[data-city]').forEach(b=>b.onclick=()=>{$('#city').value=b.dataset.city;setMode('city');searchCity(b.dataset.city)});
function renderPKResults(matches){$('#pk-results').innerHTML='';message(matches.length>1?`${matches.length} correspondances : choisissez le côté et la section avant de copier une position.`:matches.length?'Borne documentée trouvée. Vérifiez le sens et les accès.':'Aucune borne correspondante : position non déterminée.',!matches.length);if(!matches.length){$('#pk-results').innerHTML='<p class="notice">Aucune borne correspondante dans les données consultées. Position non déterminée. Vérifiez la route, le pays, le sens et le numéro ; les secteurs hors couverture restent inconnus.</p>';return}const p=document.createElement('p');p.className='micro';p.textContent=matches.length>1?`${matches.length} correspondances documentées. Sélectionnez le côté / la section : une même valeur peut désigner plusieurs points.`:'Une borne correspondante documentée. Sa précision dépend de la source.';$('#pk-results').append(p);for(const match of matches){const b=document.createElement('button');b.className='result-card';b.innerHTML=`<strong>${esc(match.road)} · ${match.unit||'PK'} ${match.value}</strong><small>${esc(match.direction||'Sens non renseigné')} · ${esc(match.section||'Section non renseignée')}</small><small>${esc(match.source)} · ${esc(match.status||'')}</small>`;b.onclick=()=>{map.setView([match.lat,match.lon],15);selectPoint(match)};$('#pk-results').append(b)}if(matches.length===1){map.setView([matches[0].lat,matches[0].lon],15);selectPoint(matches[0])}else map.fitBounds(matches.map(p=>[p.lat,p.lon]),{padding:[60,60],maxZoom:15})}
async function queryRoad(country,road){const c=config.countries[country];const escaped=road.trim().replace(/[^A-Za-z0-9 -]/g,'').replace(/\s/g,'');if(!escaped)throw new Error('Référence de route invalide.');const pattern=escaped.split('').map(ch=>ch==='-'?'[- ]?':ch).join('');const query=`[out:json][timeout:30];area["ISO3166-1"="${country}"][admin_level=2]->.a;node(area.a)[highway=milestone][ref~"^${pattern}$",i];out tags;`;const j=await overpass(query);const data=digestOSM(j,country);addData(data);renderMap();updateCoverage();return data.pks}
$('#pk-form').onsubmit=async e=>{e.preventDefault();clearSelection();const token=++pkToken;const country=$('#country').value,road=$('#road').value.trim(),pk=parsePK($('#pk').value);if(!Number.isFinite(pk)){toast('Saisissez une valeur numérique, par exemple 257 ou 257+000.');return}$('#map-title').textContent=`${road} · borne ${pk} · recherche / choix requis`;busy($('#pk-form'),true);try{let found=pkMatches(records,country,road,pk);if(!found.length){$('#pk-results').textContent='Borne absente du secteur intégré. Consultation complémentaire d’OpenStreetMap…';await queryRoad(country,road);if(token!==pkToken)return;found=pkMatches(records,country,road,pk)}if(token!==pkToken)return;renderPKResults(found)}catch(err){if(token!==pkToken)return;$('#pk-results').innerHTML=`<p class="notice">Aucune position confirmée. ${esc(errorText(err))} La couverture intégrée est partielle.</p>`}finally{if(token===pkToken)busy($('#pk-form'),false)}};
async function nearby(p){const local=pois.filter(q=>distance(p,q)<=1500);if(inSnapshot(p,1500))return {points:local,coverage:'Secteur OSM intégré (rayon 1,5 km), données partielles.'};try{const q=`[out:json][timeout:25];(nwr(around:1500,${p.lat},${p.lon})[amenity~"^(pharmacy|fuel|restaurant|fast_food|cafe|townhall|police|hospital|school|bank|place_of_worship|library|post_office|fire_station)$"];nwr(around:1500,${p.lat},${p.lon})[shop];nwr(around:1500,${p.lat},${p.lon})[historic];nwr(around:1500,${p.lat},${p.lon})[tourism];nwr(around:1500,${p.lat},${p.lon})[office=government];way(around:1500,${p.lat},${p.lon})[junction=roundabout];);out center tags;`;addData(digestOSM(await overpass(q)));return {points:pois.filter(q=>distance(p,q)<=1500),coverage:'Recherche OSM dans un rayon de 1,5 km ; inventaire non exhaustif.'}}catch(e){return {points:local,coverage:'Recherche de proximité indisponible : '+errorText(e)+' Résultats éventuellement issus du secteur intégré.'}}}
function renderSelection(){const s=selection;if(!s)return;const near=selectedPOIs.slice(0,10);$('#selection').hidden=false;$('#selection').innerHTML=`<div class="eyebrow">FICHE DE LOCALISATION</div><h2>${esc(s.road?`${s.road} · ${s.unit||'PK'} ${s.value}`:s.name||'Point sélectionné')}</h2><div class="coord">${s.lat.toFixed(6)}, ${s.lon.toFixed(6)}</div><p class="source">${esc(s.kind||'Point choisi sur la carte — présence de la personne non vérifiée')}<br>${esc(s.source||'Sélection manuelle')} ${s.retrieved?'· '+esc(s.retrieved):''}${s.section?'<br>Section '+esc(s.section)+' · '+esc(s.direction||'Sens inconnu'):''}${s.sourceUpdated?'<br>Date de l’objet : '+esc(s.sourceUpdated.slice(0,10)):''}${s.url?'<br><a target="_blank" rel="noopener" href="'+esc(s.url)+'">Consulter la donnée source ↗</a>':''}</p><p class="address">${esc(s.address||'Recherche de l’adresse proche…')}</p><p class="source">L’adresse proche et les centres de bâtiments ne garantissent pas un accès au point choisi.</p><div class="copy-actions"><button id="copy-gps">Copier GPS</button><button id="copy-sheet">Copier la fiche</button></div><div class="external"><a target="_blank" rel="noopener noreferrer" href="https://www.google.com/maps/search/?api=1&query=${s.lat},${s.lon}">Google Maps ↗</a><a target="_blank" rel="noopener noreferrer" href="https://earth.google.com/web/@${s.lat},${s.lon},0a,1500d,35y,0h,0t,0r">Google Earth ↗</a></div><div class="section-heading">REPÈRES PROCHES <span>à vol d’oiseau</span></div><p class="micro">${esc(s.coverage||'Recherche des points d’intérêt…')}</p><div class="poi-list">${near.length?near.map((p,i)=>`<button class="poi-row" data-poi="${i}"><span>${esc(pointName(p))}<small>${esc(category(p))} · OpenStreetMap</small></span><span>${meters(distance(s,p))} ↗</span></button>`).join(''):s.nearDone?'<p class="micro">Aucun repère trouvé dans les données disponibles. Cela ne signifie pas qu’il n’en existe pas.</p>':''}</div>${s.road?'<div class="section-heading">BORNES VOISINES · MÊME SECTION</div><div id="neighbors"></div>':''}`;$('#copy-gps').onclick=()=>copy(`${s.lat.toFixed(6)}, ${s.lon.toFixed(6)}`);$('#copy-sheet').onclick=()=>copy(localizationText(s,selectedPOIs,{coverage:s.nearDone?s.coverage:'Recherche des repères en cours : fiche provisoire, inventaire non vérifié.'}));$$('[data-poi]').forEach(b=>b.onclick=()=>{const p=near[+b.dataset.poi];map.setView([p.lat,p.lon],17);L.popup().setLatLng([p.lat,p.lon]).setContent(`<strong>${esc(pointName(p))}</strong><br>${esc(category(p))}<br><a href="${p.url}" target="_blank" rel="noopener">Voir la source OSM ↗</a>`).openOn(map)});if(s.road){const ns=neighbors(records,s);$('#neighbors').innerHTML=ns.length?'':'<p class="micro">Aucune borne voisine de la même section dans les données intégrées.</p>';for(const n of ns){const b=document.createElement('button');b.className='result-card';b.textContent=`${n.road} · ${n.unit||'PK'} ${n.value} · ${meters(distance(s,n))} à vol d’oiseau`;b.onclick=()=>{map.setView([n.lat,n.lon],16);selectPoint(n)};$('#neighbors').append(b)}}}
async function selectPoint(p){const token=++selectionToken;selection={...p};selectedPOIs=[];selectionLayer.clearLayers();L.marker([p.lat,p.lon],{icon:L.divIcon({className:'selected-pin',iconSize:[20,20]})}).addTo(selectionLayer);$('#map-title').textContent=p.road?`${p.road} · ${p.unit||'PK'} ${p.value}`:'Point sélectionné · WGS84';document.querySelector('.sidebar').classList.remove('collapsed');renderSelection();$('#selection').scrollIntoView({behavior:'smooth',block:'nearest'});const addressPromise=nominatim('reverse',{lat:p.lat,lon:p.lon,zoom:'18'}).then(j=>j.error?'Adresse non disponible.':j.display_name||'Adresse non disponible.').catch(e=>'Adresse non disponible : '+errorText(e));const nearbyPromise=nearby(p);const address=await addressPromise;if(token!==selectionToken)return;selection.address=address;renderSelection();const near=await nearbyPromise;if(token!==selectionToken)return;selectedPOIs=near.points.sort((a,b)=>distance(p,a)-distance(p,b));selection.coverage=near.coverage;selection.nearDone=true;renderSelection();renderMap();message(`${selectedPOIs.length} repères documentés à moins de 1,5 km. Distances à vol d’oiseau ; vérifiez le sens et les accès.`)}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copié dans le presse-papiers.')}catch{showDialog('<h3>Copier la localisation</h3><p>Sélectionnez le texte ci-dessous pour le copier.</p><textarea rows="12" id="copy-fallback"></textarea>');$('#copy-fallback').value=text;$('#copy-fallback').select()}}
$('#pin-mode').onclick=()=>{pinArmed=!pinArmed;$('#pin-mode').classList.toggle('armed',pinArmed);message(pinArmed?'Cliquez sur la carte pour placer un point. Sur mobile : appui long ou sélectionnez le centre.':'Appui long ou clic droit sur la carte pour sélectionner une position.');if(pinArmed)document.querySelector('.sidebar').classList.add('collapsed')};
function place(p){pinArmed=false;$('#pin-mode').classList.remove('armed');candidateLayer.clearLayers();selectPoint({lat:p.lat,lon:p.lng??p.lon,kind:'Point choisi sur la carte — position déclarée, non vérifiée sur place',source:'Sélection manuelle sur fond cartographique'})}
map.on('contextmenu',e=>{e.originalEvent?.preventDefault();place(e.latlng)});map.on('click',e=>{if(pinArmed)place(e.latlng)});$('#center-pick').onclick=()=>place(map.getCenter());
let longTimer,longStart;const container=$('#map');container.addEventListener('pointerdown',e=>{if(e.pointerType!=='touch')return;longStart={x:e.clientX,y:e.clientY};longTimer=setTimeout(()=>{map.dragging.disable();place(map.mouseEventToLatLng(e));setTimeout(()=>map.dragging.enable(),150)},700)});container.addEventListener('pointermove',e=>{if(longStart&&Math.hypot(e.clientX-longStart.x,e.clientY-longStart.y)>12)clearTimeout(longTimer)});['pointerup','pointercancel'].forEach(type=>container.addEventListener(type,()=>{clearTimeout(longTimer);longStart=null}));
$('#center-pick').oncontextmenu=e=>e.preventDefault();
async function loadArea(){if(liveBusy)return;const b=map.getBounds(),center=map.getCenter();if(map.getZoom()<10){message('Zoomez au moins au niveau 10 pour limiter la zone de recherche.',true);return}liveBusy=true;$('#load-area').disabled=true;message('Recherche des données cartographiques de cette zone…');try{const bbox=[b.getSouth(),b.getWest(),b.getNorth(),b.getEast()].map(v=>v.toFixed(6)).join(',');const poi=map.getZoom()>=14?`nwr(${bbox})[amenity];nwr(${bbox})[shop];nwr(${bbox})[tourism];nwr(${bbox})[historic];nwr(${bbox})[office=government];way(${bbox})[junction=roundabout];`:'';const j=await overpass(`[out:json][timeout:30];(${poi}node(${bbox})[highway=milestone];);out center tags;way(${bbox})[highway~"^(motorway|trunk)$"];out geom;`);let country;try{const r=await nominatim('reverse',{lat:center.lat,lon:center.lng,zoom:'3'});country=r.address?.country_code?.toUpperCase()}catch{}addData(digestOSM(j,country));renderMap();message(`${j.elements.length} éléments OSM chargés. ${map.getZoom()<14?'Zoomez à 14 puis relancez pour les points d’intérêt.':'Inventaire communautaire partiel ; les bornes sans numéro ou route sont exclues.'}`)}catch(e){message(errorText(e)+' Les données intégrées restent disponibles.',true)}finally{liveBusy=false;$('#load-area').disabled=false}}
$('#load-area').onclick=loadArea;
$('#clue-form').onsubmit=async e=>{e.preventDefault();clearSelection();const token=++clueToken;busy($('#clue-form'),true);$('#clue-results').textContent='Analyse des indices…';candidateLayer.clearLayers();try{const clueList=extractClues($('#clues').value);if(!clueList.length)throw new Error('Précisez un établissement, un monument ou un type de repère.');const zone=$('#zone').value;let pool;let coverage;if(zone!=='viewport'){const c=snapshot.cities[zone];map.setView([c.lat,c.lon],13);pool=pois.filter(p=>p.lat>=c.bbox[0]&&p.lat<=c.bbox[2]&&p.lon>=c.bbox[1]&&p.lon<=c.bbox[3]);coverage=`Secteur central intégré de ${c.name}, données du ${c.retrieved}. Couverture OSM partielle.`}else{const b=map.getBounds();if(distance({lat:b.getSouth(),lon:b.getWest()},{lat:b.getNorth(),lon:b.getEast()})>25000)throw new Error('Zone trop vaste : zoomez davantage ou choisissez Valencia / Angers.');pool=pois.filter(p=>b.contains([p.lat,p.lon]));const c=inSnapshot({lat:map.getCenter().lat,lon:map.getCenter().lng});if(!c||!pool.length){const bbox=[b.getSouth(),b.getWest(),b.getNorth(),b.getEast()].map(x=>x.toFixed(6)).join(',');const j=await overpass(`[out:json][timeout:30];(nwr(${bbox})[amenity];nwr(${bbox})[shop];nwr(${bbox})[tourism];nwr(${bbox})[historic];nwr(${bbox})[office=government];way(${bbox})[junction=roundabout];);out center tags;`);addData(digestOSM(j));pool=pois.filter(p=>b.contains([p.lat,p.lon]))}coverage='Zone visible sur la carte ; inventaire OSM partiel.'}if(token!==clueToken)return;$('#map-title').textContent=zone==='viewport'?'Zones candidates · périmètre recherché':`${snapshot.cities[zone].name} · zones candidates`;const radius=+$('#radius').value,found=candidates(pool,clueList,radius);$('#clue-results').innerHTML=`<p class="micro">Indices recherchés : ${clueList.map(c=>esc(c.label)).join(' · ')}<br>${esc(coverage)}<br>Centres de bâtiments possibles. La proximité seule ne prouve ni la visibilité ni l’accès. Rayon : ${radius} m.</p>`;if(!found.length){$('#clue-results').innerHTML+='<p class="notice">Aucune concordance dans les données consultées. Essayez une autre zone ou des indices plus précis. Les données manquantes ne prouvent pas l’absence d’un établissement.</p>';message('Aucune zone candidate trouvée. Position inconnue.',true);return}found.forEach((c,i)=>{const matched=clueList.filter((_,k)=>c.evidence[k]).map(c=>c.label),missing=clueList.filter((_,k)=>!c.evidence[k]).map(c=>c.label);L.circle([c.lat,c.lon],{radius,color:'#e8bd71',weight:1.5,dashArray:'5 5',fillOpacity:.1}).addTo(candidateLayer);const m=L.marker([c.lat,c.lon],{icon:L.divIcon({className:'candidate-number',html:i+1,iconSize:[27,27]})}).addTo(candidateLayer);const b=document.createElement('button');b.className='result-card';b.innerHTML=`<strong>Zone candidate ${i+1} · ${c.count}/${clueList.length} indices</strong><small class="match">Concordants : ${esc(matched.join(', '))}</small><small class="missing">Non retrouvés : ${esc(missing.join(', ')||'aucun dans ce rayon')}</small><small>${c.evidence.filter(Boolean).map(p=>esc(pointName(p))).join(' · ')}<br>Hypothèse de proximité, jamais une position confirmée.</small>`;const focus=()=>{map.setView([c.lat,c.lon],15);const evidence=c.anchor;selectPoint({...evidence,name:`Zone candidate ${i+1}`,kind:`HYPOTHÈSE — zone de ${radius} m autour d’un repère ; position de la personne inconnue`,source:'Recoupement de repères OpenStreetMap'})};b.onclick=focus;m.on('click',focus);$('#clue-results').append(b)});map.fitBounds(found.map(p=>[p.lat,p.lon]),{padding:[70,70],maxZoom:14});message(`${found.length} zones candidates. Comparez les repères avec votre interlocuteur ; aucune position n’est confirmée.`);renderMap()}catch(err){$('#clue-results').innerHTML=`<p class="notice">${esc(errorText(err))}</p>`}finally{busy($('#clue-form'),false)}};
function setBase(type){const sat=type==='satellite';if(sat){if(!satellite){satellite=L.tileLayer(config.satellite.url,{maxZoom:19,attribution:config.satellite.attribution});satellite.on('tileerror',()=>message('Imagerie satellite indisponible sur certaines tuiles. Revenez à la vue Carte.',true))}map.removeLayer(standard);satellite.addTo(map)}else{if(satellite)map.removeLayer(satellite);standard.addTo(map)}$('.map-stage').classList.toggle('satellite-view',sat);$('#base-map').classList.toggle('active',!sat);$('#base-satellite').classList.toggle('active',sat)}
$('#base-map').onclick=()=>setBase('map');$('#base-satellite').onclick=()=>setBase('satellite');fallbackTiles.on('tileerror',()=>message('Certaines tuiles ne répondent pas. Les positions et repères intégrés restent consultables.',true));
function showDialog(html){$('#info-content').innerHTML=html;$('#info-dialog').showModal()}
function sources(){showDialog(`<p>Un outil d’aide à la localisation pendant un appel. Les coordonnées désignent un point cartographique, jamais la présence confirmée d’une personne.</p><h3>Couverture actuelle</h3><table><tr><th>Pays</th><th>Référentiel intégré</th></tr>${Object.entries(config.countries).map(([c,v])=>`<tr><td>${v.name}</td><td>${c==='ES'?'Bornes officielles · secteur de Valencia':c==='FR'?'PR officiels valides · secteur d’Angers':'OpenStreetMap sur demande ; aucun référentiel officiel intégré'}</td></tr>`).join('')}</table><p>${records.length} bornes documentées actuellement chargées. Couverture partielle, sans interpolation. Plusieurs sens ou sections peuvent porter le même numéro. Les points calculés du référentiel français ont été exclus.</p><h3>Provenance et licences</h3><p><a href="https://api-features.idee.es/collections/markerpost" target="_blank" rel="noopener">IGN / CNIG Espagne — IGR Redes de Transporte</a> · Obra derivada de IGR-RT CC-BY 4.0 ign.es. Identifiants des routes reliés aux bornes à partir des données officielles. <a href="https://geoservices.ign.fr/bdtopo" target="_blank" rel="noopener">IGN France — BD TOPO®, points de repère</a> · Licence Ouverte 2.0. ${esc(snapshot.retrieved)} : date de récupération, distincte de la date de mise à jour des objets.</p><p>Repères et axes : <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">© OpenStreetMap contributors, ODbL</a>. Les géométries des établissements peuvent être leur centre, pas leur entrée. Adresse proche : Nominatim / OpenStreetMap. Satellite : ${esc(config.satellite.credit)}. Fond Carte : OpenFreeMap / OpenMapTiles / OpenStreetMap ; fond Esri Light Gray de secours si WebGL ou les tuiles vectorielles sont indisponibles. Ce fond de secours est ancien et ne garantit pas les changements routiers récents ; ses services sont annoncés en retrait en décembre 2029. Bibliothèques : Leaflet 1.9.4, MapLibre GL 5.6.2 et MapLibre GL Leaflet, licences BSD. Ces licences de données restent applicables indépendamment du copyright de l’application.</p><h3>Recherche par indices</h3><p>Analyse de mots-clés et noms d’établissements dans les données OSM de la zone choisie. Types reconnus : pharmacie, rond-point, station-service, restaurant, café, mairie, église, hôpital, musée, banque, école et monument. Les autres mots servent à chercher un nom. Les zones candidates utilisent la distance à vol d’oiseau entre les repères, sans analyse de visibilité ni d’itinéraire. Aucun pourcentage de certitude n’est calculé.</p><h3>Installation et hors connexion</h3><p>Sur iPhone : ouvrir dans Safari, Partager, puis « Sur l’écran d’accueil ». Sur ordinateur : utiliser l’option d’installation du navigateur. L’interface et les secteurs intégrés peuvent être mis en cache ; les fonds de carte, les nouvelles adresses et les recherches externes nécessitent Internet. L’installation sur un appareil physique reste à valider.</p><h3>Confidentialité et disponibilité</h3><p>Aucun compte, aucun suivi publicitaire. Les recherches et coordonnées sélectionnées sont transmises au service cartographique correspondant (Nominatim pour l’adresse, Overpass pour les repères). Aucun accès GPS automatique. Les services publics gratuits peuvent être limités ou indisponibles. Recherche de ville à la validation uniquement, requêtes Nominatim espacées et mises en cache. Ce site statique ne dispose pas d’un quota partagé entre tous les utilisateurs.</p><h3>Services configurables</h3><p>Pour changer de fournisseur Nominatim sans modifier l’application, indiquez une URL de service compatible. Aucune clé secrète ne doit être saisie.</p><label for="nom-endpoint">URL Nominatim</label><input id="nom-endpoint" type="url" value="${esc(config.nominatim)}"><button class="primary" id="save-endpoint">Enregistrer ce fournisseur</button><p>© 2026 Benjamin Daguier — Tous droits réservés.</p>`);$('#save-endpoint').onclick=()=>{try{const u=new URL($('#nom-endpoint').value);if(u.protocol!=='https:')throw new Error();config.nominatim=u.href.replace(/\/$/,'');localStorage.setItem('pk-nominatim',config.nominatim);toast('Fournisseur enregistré pour cet appareil.')}catch{toast('Indiquez une URL HTTPS valide.')}}}
$('#help').onclick=sources;$('#sources').onclick=sources;$('.dialog-close').onclick=()=>$('#info-dialog').close();$('#info-dialog').onclick=e=>{if(e.target===$('#info-dialog'))$('#info-dialog').close()};
$('#mobile-panel').onclick=()=>{document.querySelector('.sidebar').classList.toggle('collapsed');map.invalidateSize()};
let installPrompt;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});$('#install').onclick=async()=>{if(installPrompt){installPrompt.prompt();await installPrompt.userChoice;installPrompt=null}else showDialog('<h3>Installer PK Locator</h3><p>Sur iPhone : ouvrez le site dans Safari, touchez Partager, puis « Sur l’écran d’accueil ».</p><p>Sur ordinateur : utilisez l’icône d’installation dans la barre d’adresse ou le menu du navigateur. Une connexion initiale est nécessaire.</p>')};
function connectivity(){$('#connection').textContent=navigator.onLine?'En ligne':'Hors connexion';if(!navigator.onLine)message('Hors connexion : données intégrées consultables ; fonds de carte et recherches externes indisponibles.',true)}window.addEventListener('online',connectivity);window.addEventListener('offline',connectivity);
async function init(){try{[config,snapshot]=await Promise.all([jsonFetch('./config.json'),jsonFetch('./data/catalog.json')]);try{const u=localStorage.getItem('pk-nominatim');if(u&&new URL(u).protocol==='https:')config.nominatim=u}catch{}const datasets=await Promise.all(snapshot.files.map(f=>jsonFetch('./data/'+f)));datasets.forEach(addData);updateCoverage();const c=snapshot.cities.Valencia;showCity(c,c.name);connectivity();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>toast('Le cache hors connexion n’a pas pu être activé.'));}catch(e){message('Impossible de charger les données intégrées. '+errorText(e),true);$('#city-results').textContent='Rechargez le site avec une connexion Internet.'}}
init();
